 * SPDX-License-Identifier: Apache-2.0
 *
 * This driver creates fake eSPI buses which can contain emulated devices
 * (implemented by a separate emulation driver). The API between this driver
 * and the emulators attached to its bus is defined in
 * include/zephyr/drivers/espi_emul.h.
 */

#define DT_DRV_COMPAT zephyr_espi_emul_controller

#define LOG_LEVEL CONFIG_ESPI_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(espi_emul_ctlr);

#include <zephyr/device.h>
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/espi.h>
#include <zephyr/drivers/espi_emul.h>

/** Working data for the controller */
struct espi_emul_data {
	/* List of struct espi_emul associated with the device */
	sys_slist_t emuls;
	/* eSPI host configuration */
	struct espi_cfg cfg;
	/* List of eSPI callbacks */
	sys_slist_t callbacks;
};

static struct espi_emul *espi_emul_find(const struct device *dev,
					unsigned int chipsel)
{
	struct espi_emul_data *data = dev->data;
	sys_snode_t *node;

	SYS_SLIST_FOR_EACH_NODE(&data->emuls, node) {
		struct espi_emul *emul;

		emul = CONTAINER_OF(node, struct espi_emul, node);
		if (emul->chipsel == chipsel) {
			return emul;
		}
	}

	return NULL;
}

static int espi_emul_config(const struct device *dev, struct espi_cfg *cfg)
{
	struct espi_emul_data *data = dev->data;

	__ASSERT_NO_MSG(cfg);

	data->cfg = *cfg;

	return 0;
}

static bool espi_emul_get_channel_status(const struct device *dev,
					 enum espi_channel ch)
{
	return (ch == ESPI_CHANNEL_VWIR || ch == ESPI_CHANNEL_PERIPHERAL);
}

static int espi_emul_send_vwire(const struct device *dev,
				enum espi_vwire_signal signal, uint8_t level)
{
	const struct emul_espi_driver_api *api;
	struct espi_emul *emul;

	/*
	 * For strict hardware compatibility, there may be placed
	 * assertion on direction, e.g.
	 * __ASSERT(vwire_is_controller_to_target(signal),
	 *          "Invalid signal direction: %d", signal);
	 * Currently wait explicitly on concrete requirements.
	 */
	emul = espi_emul_find(dev, EMUL_ESPI_HOST_CHIPSEL);
	if (!emul) {
		LOG_DBG("espi_emul not found");
		return -EIO;
	}

	__ASSERT_NO_MSG(emul->api);
	__ASSERT_NO_MSG(emul->api->set_vw);
	api = emul->api;

	return api->set_vw(emul->target, signal, level);
}

static int espi_emul_receive_vwire(const struct device *dev,
				   enum espi_vwire_signal signal,
				   uint8_t *level)
{
	const struct emul_espi_driver_api *api;
	struct espi_emul *emul;

	__ASSERT_NO_MSG(level);

	emul = espi_emul_find(dev, EMUL_ESPI_HOST_CHIPSEL);
	if (!emul) {
		LOG_DBG("espi_emul not found");
		return -EIO;
	}

	__ASSERT_NO_MSG(emul->api);
	__ASSERT_NO_MSG(emul->api->get_vw);
	api = emul->api;

	return api->get_vw(emul->target, signal, level);
}

static int espi_emul_manage_callback(const struct device *dev,
				     struct espi_callback * callback, bool set)
{
	struct espi_emul_data *data = dev->data;

	return espi_manage_callback(&data->callbacks, callback, set);
}

static int espi_emul_read_lpc_request(const struct device *dev,
				      enum lpc_peripheral_opcode op,
				      uint32_t *data)
{
	ARG_UNUSED(dev);
	ARG_UNUSED(op);
	ARG_UNUSED(data);

	return -ENOTSUP;
}

static int espi_emul_write_lpc_request(const struct device *dev,
				       enum lpc_peripheral_opcode op,
				       uint32_t *data)
{
	const struct emul_espi_driver_api *api;
	struct espi_emul *emul;

	__ASSERT_NO_MSG(data);

	emul = espi_emul_find(dev, EMUL_ESPI_HOST_CHIPSEL);
	if (!emul) {
		LOG_DBG("espi_emul not found");
		return -EIO;
	}
	__ASSERT_NO_MSG(emul->api);

	api = emul->api;

#ifdef CONFIG_ESPI_PERIPHERAL_ACPI_SHM_REGION
	if (op == EACPI_WRITE_CHAR) {
		if (!api->port_write) {
			return -ENOTSUP;
		}
		return api->port_write(emul->target, *data);
	}
#endif

	return -ENOTSUP;
}

static int emul_espi_trigger_event(const struct device *espi_dev,
				   struct espi_event *evt)
{
	struct espi_emul_data *data = espi_dev->data;

	if ((evt->evt_type & ESPI_BUS_EVENT_VWIRE_RECEIVED) &&
	    !(data->cfg.channel_caps & ESPI_CHANNEL_VWIR)) {
		return -EIO;
	}

	espi_send_callbacks(&data->callbacks, espi_dev, *evt);

	return 0;
}

/**
 * Set up a new emulator and add it to the list
 *
 * @param dev eSPI emulation controller device
 */
static int espi_emul_init(const struct device *dev)
{
	struct espi_emul_data *data = dev->data;

	sys_slist_init(&data->emuls);

	return emul_init_for_bus(dev);
}

int espi_emul_register(const struct device *dev, struct espi_emul *emul)
{
	struct espi_emul_data *data = dev->data;
	const char *name = emul->target->dev->name;

	sys_slist_append(&data->emuls, &emul->node);

	LOG_INF("Register emulator '%s' at cs %u\n", name, emul->chipsel);

	return 0;
}

/* Device instantiation */

static const struct emul_espi_device_api emul_espi_dev_api = {
	.trigger_event = emul_espi_trigger_event,
	.find_emul = espi_emul_find
};

static const struct espi_driver_api espi_emul_api = {
	.config = espi_emul_config,
	.get_channel_status = espi_emul_get_channel_status,
	.send_vwire = espi_emul_send_vwire,
	.receive_vwire = espi_emul_receive_vwire,
	.manage_callback = espi_emul_manage_callback,
	.read_lpc_request = espi_emul_read_lpc_request,
	.write_lpc_request = espi_emul_write_lpc_request,
	.emul_api = &emul_espi_dev_api,
};

#define EMUL_LINK_AND_COMMA(node_id) {					\
	.dev = DEVICE_DT_GET(node_id),					\
},

#define ESPI_EMUL_INIT(n)						\
	static const struct emul_link_for_bus emuls_##n[] = {		\
		DT_INST_FOREACH_CHILD_STATUS_OKAY(n, EMUL_LINK_AND_COMMA) \
	};								\
	static struct emul_list_for_bus espi_emul_cfg_##n = {		\
		.children = emuls_##n,					\
		.num_children = ARRAY_SIZE(emuls_##n),			\
	};								\
	static struct espi_emul_data espi_emul_data_##n;		\
	DEVICE_DT_INST_DEFINE(n,					\
			      &espi_emul_init,				\
			      NULL,					\
			      &espi_emul_data_##n,			\
			      &espi_emul_cfg_##n,			\
			      POST_KERNEL,				\
			      CONFIG_ESPI_INIT_PRIORITY,		\
			      &espi_emul_api);

DT_INST_FOREACH_STATUS_OKAY(ESPI_EMUL_INIT)
